test("a negative charge is refused", () => {
  expect(() => splitCharge(-1, 2)).toThrow();
});

function total(shares: number[]): number {
  return shares.reduce((sum, share) => sum + share, 0);
}

test("the shares add up to exactly the charge", () => {
  expect(total(splitCharge(3333, 2))).toBe(3333);
  expect(total(splitCharge(1000, 3))).toBe(1000);
  expect(total(splitCharge(1, 4))).toBe(1);
});

test("leftover cents go to the first borrowers, one cent each", () => {
  expect(splitCharge(3333, 2)).toEqual([1667, 1666]);
  expect(splitCharge(1000, 3)).toEqual([334, 333, 333]);
  expect(splitCharge(2, 3)).toEqual([1, 1, 0]);
});

test("no share is more than one cent from another", () => {
  const shares = splitCharge(9999, 7);
  expect(Math.max(...shares) - Math.min(...shares)).toBeLessThanOrEqual(1);
});

test("an even charge gives every borrower the same share", () => {
  expect(splitCharge(3000, 3)).toEqual([1000, 1000, 1000]);
});

test("a fractional charge is refused", () => {
  expect(() => splitCharge(33.5, 2)).toThrow();
});

test("zero or fractional ways is refused", () => {
  expect(() => splitCharge(100, 0)).toThrow();
  expect(() => splitCharge(100, 1.5)).toThrow();
});

